window.SAQ_PAPER_QUESTIONS["2025-1-st-george"]=[{"number":1,"title":"","stemText":"An unimmunised 2-year-old boy presents to your Emergency Department with respiratory\ndistress and stridor.","parts":[{"id":"a","label":"Part A","prompt":"In addition to croup, list (5) important differential diagnoses you need to consider in this patient and the clinical features that help distinguish between them. (5 marks) Differential Diagnosis Clinical features"},{"id":"b","label":"Part B","prompt":"In the table below, compare the differences between (5) clinical signs for mild and moderate-severe croup. (5 marks)"},{"id":"c","label":"Part C","prompt":"List (2) initial pharmacological treatments with dose ranges and routes of administration for his moderate to severe croup. (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Drooling, neck stiffness/pain, toxic appearance</td></tr><tr><td>Foreign body aspiration</td><td>Sudden onset, history of choking</td></tr><tr><td>Epiglottitis</td><td>Drooling, muffled voice, toxic appearance, absent cough,</td></tr><tr><td colspan=\"2\">tripoding unimmunised</td></tr><tr><td>Bacterial tracheitis</td><td>Harsh cough, chest pain, toxic appearance</td></tr><tr><td>Angioedema/anaphylaxis</td><td>Itching, tongue/lip/face swelling, urticarial rash</td></tr><tr><td colspan=\"2\">Other options also considered</td></tr><tr><td colspan=\"2\">Airway trauma – neck swelling, crepitus, bruising;</td></tr><tr><td colspan=\"2\">Inhalation of hot gases – facial burns, perioral soot;</td></tr><tr><td colspan=\"2\">Infectious mononucleosis – sore throat, tonsillar enlargement;</td></tr><tr><td colspan=\"2\">Diphtheria – travel to endemic area, unimmunised,</td></tr><tr><td colspan=\"2\">Congenital causes (laryngomalacia, subglottic stenosis, vascular ring, cord paresis) – longer</td></tr><tr><td colspan=\"2\">term symptoms.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>None, or only present if</td><td>Stridor at rest</td><td></td><td></td></tr><tr><td colspan=\"4\">upset</td></tr><tr><td><strong>2.</strong></td><td>Respiratory rate</td><td>Usually normal</td><td>May be increased or</td></tr><tr><td colspan=\"4\">decreased if fatiguing</td></tr><tr><td><strong>3.</strong></td><td>Work of breathing</td><td>None</td><td>Marked</td></tr><tr><td colspan=\"4\">(chest wall retraction /</td></tr><tr><td colspan=\"4\">tracheal tug)</td></tr><tr><td><strong>4.</strong></td><td>Conscious state</td><td>Normal, alert</td><td>Irritable / decreased</td></tr><tr><td><strong>5.</strong></td><td>Cyanosis</td><td>None</td><td>Late sign only</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Dexamethasone 0.15mg/kg – 0.6mg/kg PO / IV / IM</div><div class=\"answer-line\">Other options include: Prednisolone 1mg/kg PO, Budesonide 2mg nebulised with</div><div class=\"answer-line\">oxygen. Must have adrenaline as one of the treatments.</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 45-year-old man presents to the ED after being struck in the left eye by a squash ball.\nA CT orbit was performed on arrival. An axial CT image is shown below :","parts":[{"id":"a","label":"Part A","prompt":"What is the most likely diagnosis based on this CT image? (1 mark)"},{"id":"b","label":"Part B","prompt":"List (6) findings you might find on ocular exam. (6 marks)"},{"id":"c","label":"Part C","prompt":"State (5) key steps in the immediate emergency department management of this patient. Include doses and routes where appropriate (5 marks)"}],"propPages":["asset:img4c523f36fe00e0453a"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Left globe rupture</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Dark uveal tissue prolapsing through the conjunctiva</div><div class=\"answer-line\">Distorted or teardrop-shaped pupil</div><div class=\"answer-line\">Decreased visual acuity</div><div class=\"answer-line\">Relative afferent pupillary defect (RAPD)</div><div class=\"answer-line\">Hyphaema</div><div class=\"answer-line\">Seidels sign positive (leakage of aqueous humor seen in fluroscein-stained eye)</div><div class=\"answer-line\">Large subconjunctival haemorrhage involving entire sclera <em>(very suspicious)</em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Minimal eye examination – avoid pressure or manipulation ; no topical medications</div><div class=\"answer-line\">Elevate head of bed 30-45° head up and apply rigid eye shield</div><div class=\"answer-line\">Analgesia and antiemetics with eg… to avoid increasing IOP</div><div class=\"answer-line\">Start empirical IV antibiotics eg cephazolin 1g -2gIV and update tetanus if required</div><div class=\"answer-line\">Urgent ophthalmology consultation for surgical repair</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 42-year-old man presents to ED with a 4-day history of shortness of breath on exertion,\nand a cough productive of white sputum. He has no other background history.\nHis blood pressure is 85/50, pulse 120 regular, SaO2 93% on RA.\nHis ECG is shown below :","parts":[{"id":"a","label":"Part A","prompt":"Give (3) salient findings seen in the ECG (3 marks) You perform a point-of-care cardiac ultrasound on the patient. Below is a parasternal log axis view of his heart, paused at the closing and opening of the mitral valve :"},{"id":"b","label":"Part B","prompt":"List (3) important findings on the ultrasound. (3 marks) You go on to do further cardiac views and a lung ultrasound :"},{"id":"c","label":"Part C","prompt":"State (3) further findings on these images. (3 marks)"},{"id":"d","label":"Part D","prompt":"What is the MOST LIKELY diagnosis? Give (2) possible causes of this diagnosis in any patient. (3 marks)"}],"propPages":["asset:imgd5c1a911eeb0e8349a","asset:img794dc699e6f0908d7e","asset:img173280c8092774a822","asset:imgbe6d199ddac713fd71","asset:imgdd93c6490ebd2eb699","asset:img587caa913b98ad2051"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Sinus tachycardia</div><div class=\"answer-line\">·</div><div class=\"answer-line\">Poor R wave progression</div><div class=\"answer-line\">·</div><div class=\"answer-line\">Biphasic P wave in V1</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Dilated LA</div><div class=\"answer-line\">·</div><div class=\"answer-line\">Poor EPPS (e point septal separation) – indicating poor LV function</div><div class=\"answer-line\">·</div><div class=\"answer-line\">Pleural effusion</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Ballooning of LV on A4C view</div><div class=\"answer-line\">·</div><div class=\"answer-line\">Dilation of IVC with poor respiratory variation</div><div class=\"answer-line\">·</div><div class=\"answer-line\">Multiple B lines indicating likely pulmonary oedema.</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Most likely : dilated cardiomyopathy</td></tr><tr><td colspan=\"2\">Causes</td></tr><tr><td>·</td><td>Viral cardiomyopathy</td></tr><tr><td>·</td><td>Alcoholic cardiomyopathy</td></tr><tr><td>·</td><td>Post partum cardiomyopathy</td></tr><tr><td>·</td><td>Medications (eg chemotherapy)</td></tr><tr><td colspan=\"2\">Hypertension</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 1-year-old presents with facial burns from gas oven explosion.\nHe has a hoarse voice, stridor, 92% saturations in room air and 40 % TBSA partial and full thickness burns. A clinical photo is shown below :","parts":[{"id":"a","label":"Part A","prompt":"Describe your airway concerns. (4 marks)"},{"id":"b","label":"Part B","prompt":"Outline your airway management in sequential order. (4 marks)"},{"id":"c","label":"Part C","prompt":"In addition to airway, state your other acute management. (4 marks)"}],"propPages":["asset:img0fa0592500b52766e9"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">A 1-year-old presents with facial burns from gas oven explosion.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">He has a hoarse voice, stridor, 92% saturations in room air and 40 % TBSA partial and full</div><div class=\"answer-line\">thickness burns.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>A clinical photo is shown below : </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A nurse has asked you to check position of this nasogastric tube on chest X-ray, inserted by\n• ne of your medical students :","parts":[{"id":"a","label":"Part A","prompt":"List (3) relevant findings on this image. (3 marks)"},{"id":"b","label":"Part B","prompt":"List (3) immediate clinical actions you would take. (3 marks)"},{"id":"c","label":"Part C","prompt":"Outline (6) steps you would take in managing this incident. (6 marks)"}],"propPages":["asset:imgd6cd074a13b9fbbcbd"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">NGT has gone down R main bronchus</div><div class=\"answer-line\"><strong>2.</strong></div><div class=\"answer-line\">Iatrogenic R-sided pneumothorax</div><div class=\"answer-line\"><strong>3.</strong></div><div class=\"answer-line\">R basal opacification – unlikely to be fluid as would expect horizontal air-fluid</div><div class=\"answer-line\">interface</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Immediate removal of misplaced NGT</div><div class=\"answer-line\"><strong>2.</strong></div><div class=\"answer-line\">Supportive : ensure patient clinically stable, provide oxygen and analgesia</div><div class=\"answer-line\"><strong>3.</strong></div><div class=\"answer-line\">Insert R small-bore ICC to treat iatrogenic injury</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><strong>Open disclosure</strong> of event to patient / relatives</td></tr><tr><td><strong>2.</strong></td><td><strong>Document</strong> the incident and discussion with patient</td></tr><tr><td><strong>3.</strong></td><td><strong>Notify incident</strong> via hospital’s Incident Management Database</td></tr><tr><td><strong>4.</strong></td><td><strong>Counsel / debrief</strong> the student and the supervising RN / MO</td></tr><tr><td colspan=\"2\">Notify student’s clinical supervisor and review policy/procedure for clinical</td></tr><tr><td colspan=\"2\"><strong>5.</strong></td></tr><tr><td colspan=\"2\">supervision of medical students</td></tr><tr><td><strong>6.</strong></td><td>Refer for review and education via M+M</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 75-year-old female presents with right knee pain after falling from a 1.5m height. Her\nknee is extremely swollen.","parts":[{"id":"a","label":"Part A","prompt":"Other than an inability to weight bear, list (4) components of a validated criteria for performing an X-ray in this patient. (4 marks) An AP X-ray of the patient’s knee is provided below :"},{"id":"b","label":"Part B","prompt":"List (3) abnormalities show in this X-ray. (3 marks)"},{"id":"c","label":"Part C","prompt":"List (4) acute complications of this injury. (4 marks) The knee is reduced under procedural sedation. A post-procedure X-ray is obtained to ensure joint alignment."},{"id":"d","label":"Part D","prompt":"What is the most important next investigation to perform in this patient. (1 mark)"}],"propPages":["asset:img340262cf03e99db086"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Age 55 or over</div><div class=\"answer-line\">Fibula head tenderness</div><div class=\"answer-line\">Isolated patellar tenderness</div><div class=\"answer-line\">Active knee flexion to 90 degrees</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Lateral knee dislocation</div><div class=\"answer-line\">Tibial plateau fracture</div><div class=\"answer-line\">Intra-articular extension</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Popliteal artery (and vein) injury (35-40%)</div><div class=\"answer-line\">Peroneal nerve injury (25-30%)</div><div class=\"answer-line\">Compartment syndrome</div><div class=\"answer-line\">Potential amputation (80% chance if reduction is delayed &gt;8 hours!)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">CT angiography (CT alone does not get a mark)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 12-month-old girl is brought to your Emergency Department with two days of vomiting,\nfevers, rhinorrhoea and lethargy. Her vitals are as follows :\n\nHR 170, RR 45, SaO2 99%RA, Temp 39.5°C","parts":[{"id":"a","label":"Part A","prompt":"List (4) potential causes for this child’s signs and symptoms. (4 marks) A VBG is performed and shown below :\n\npH\n7.30\n\npCO2\n\nPO2\n\nHCO3\n13.4\n\nBE -\n9.7\n\nNa\n110\n\nK\n7.5\n\nCl\nIonised Ca 1.16\n\nGlucose\n3.0\n\nLactate\n2.2\n\nCreatinine\n\nHb\n145 You assess the patient as having moderate to severe dehydration."},{"id":"b","label":"Part B","prompt":"List (4) abnormalities in this VBG and state at least (2) actions you will undertake to address each. (8 marks) Abnormality Actions"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Viral illness</td></tr><tr><td colspan=\"2\">Meningitis</td></tr><tr><td colspan=\"2\">First presentation of DKA</td></tr><tr><td colspan=\"2\">Other differential although significantly less common : bacteraemia, NAI with ICH</td></tr><tr><td colspan=\"2\"><em>Not gastroenteritis given no reported diarrhoea</em></td></tr><tr><td colspan=\"2\"><strong>A VBG is performed and shown below :</strong></td></tr><tr><td>pH</td><td>7.30</td></tr><tr><td>pCO2</td><td>24</td></tr><tr><td>PO2</td><td>39</td></tr><tr><td>HCO3</td><td>13.4</td></tr><tr><td>BE -</td><td>9.7</td></tr><tr><td>Na</td><td>110</td></tr><tr><td>K</td><td>7.5</td></tr><tr><td>Cl</td><td>81</td></tr><tr><td>Ionised Ca</td><td>1.16</td></tr><tr><td>Glucose</td><td>3.0</td></tr><tr><td>Lactate</td><td>2.2</td></tr><tr><td>Creatinine</td><td>76</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Hyperkalaemia</td><td>Cardiac monitoring</td></tr><tr><td colspan=\"2\">If ECG abnormal give calcium gluconate 0.1mmol/kg IV over 3-5</td></tr><tr><td colspan=\"2\">minutes</td></tr><tr><td colspan=\"2\">Dextrose 10% 5ml/kg IV (will stimulate endogenous insulin)</td></tr><tr><td colspan=\"2\">Nebulised salbutamol 2.5mg</td></tr><tr><td>Hypoglycaemia</td><td>2mL/kg 10% dextrose IV</td></tr><tr><td colspan=\"2\">Omit insulin for hyperK as dextrose bolus will stimulate endogenous</td></tr><tr><td colspan=\"2\">insulin</td></tr><tr><td colspan=\"2\">Monitor BSL q15min</td></tr><tr><td>Hyponatraemia</td><td>Give 0.9% saline with 5% dextrose for maintenance</td></tr><tr><td>(likely hypovolaemic +/-</td><td>Check S.Na q4-6h, ensure no more than 8mmol/L rise in 24h</td></tr><tr><td>SIADH)</td><td>Monitor for CNS symptoms – 3mL/kg 3% saline if seizures</td></tr><tr><td colspan=\"2\">Paired serum and urine osmol/Na</td></tr><tr><td>AKI – likely prerenal</td><td>0.9% sodium chloride bolus 10ml/kg, aiming for cap return &lt;3secs and</td></tr><tr><td colspan=\"2\">decrease in HR to below 140</td></tr><tr><td colspan=\"2\">Then maintenance as above</td></tr><tr><td colspan=\"2\">Avoid nephrotoxins (eg NSAIDs)</td></tr><tr><td colspan=\"2\">HypoNa/HyperK ?adrenal insufficiency : IV hydrocortisone 1-2mg/kg, seek and treat infective</td></tr><tr><td colspan=\"2\">cause</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 75-year-old female presents to ED following several episodes of “collapse” at home. She has a previous medical history of AF, HTN, COPD and depression.\nInitial vital signs are: HR 58, BP 109/72, RR 16, SpO2 98% RA, temp 36.5C.\nShe becomes symptomatic whilst on the ED monitor. The following ECG is recorded :","parts":[{"id":"a","label":"Part A","prompt":"Describe and interpret this ECG. (3 marks)"},{"id":"b","label":"Part B","prompt":"Complete the table listing potential causes of this rhythm disturbance. Organise your answer into (4) categories, with (2) examples of each (8 marks). Category\nExamples x 2\nThe patient deteriorates further. HR is now 30bpm with BP 75/50. The episodes of rhythm disturbance are now more frequent and associated with brief episodes of seated syncope."},{"id":"c","label":"Part C","prompt":"Outline your management of this patient. (7 marks)"}],"propPages":["asset:img17468779544e430d57"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Paroxysm of broad complex tachycardia / polymorphic VT in the first half of the ECG</div><div class=\"answer-line\"></div><div class=\"answer-line\">Reversion to a narrow complex rhythm in the 2nd half of the ECG – likely AF with</div><div class=\"answer-line\"></div><div class=\"answer-line\">LQTS</div><div class=\"answer-line\">Interpretation (1 mark)</div><div class=\"answer-line\">Torsades de Pointes</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><strong>HypoK, hypoMag, hypoCa </strong></td></tr><tr><td>Antipsychotics</td><td>Amisulpride, haloperidol, droperidol,</td></tr><tr><td colspan=\"2\">olanzapine</td></tr><tr><td>Class IA/IC antiarrhythmics</td><td>Quinidine, procainamide, flecainide</td></tr><tr><td>TCAs</td><td>Amitriptyline, doxepin, nortriptyline</td></tr><tr><td>SSRIs</td><td>Citalopram, escitalopram</td></tr><tr><td>Macrolides</td><td>Erythromycin, clarithromycin</td></tr><tr><td>Opiates</td><td>Methadone, dextropropoxyphene</td></tr><tr><td colspan=\"2\"><em>Must have class III, electrolytes and at least one mental health drug class</em> (antidepressant or</td></tr><tr><td colspan=\"2\">antipsychotic) to pass question</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>Stop offending medications</strong> (e.g. amiodarone, sotalol)</div><div class=\"answer-line\"><strong>Fluid bolus</strong>, e.g. 500ml saline aliquots aiming for MAP&gt;65.</div><div class=\"answer-line\"><strong>Start chronotrope infusion</strong> – adrenaline preferred to isoprenaline given low BP, e.g.</div><div class=\"answer-line\">3mg/50ml at 2-10 ml/hr (= 2-10 mcg/min) Titrate aiming for HR ~100, MAP &gt;65</div><div class=\"answer-line\"><strong>Correct electrolyte abnormalities</strong> – hypoK, hypoMag, hypoCa. Can give MgSO4 load (10-</div><div class=\"answer-line\">20mmol) whilst awaiting formal bloods.</div><div class=\"answer-line\"><strong>May need cardiac pacing</strong> (transcutaneous / transvenous) if unable to adequately</div><div class=\"answer-line\">chronotrope patient with IV beta agonist alone.</div><div class=\"answer-line\">Consider need for 2nd inotropes if BP unresponsive to above – e.g. HIET, noradrenaline,</div><div class=\"answer-line\">vasopressin</div><div class=\"answer-line\">Explore whether this is a deliberate overdose and psych referral as appropriate</div><div class=\"answer-line\"><strong>Admit to ICU for haemodynamic monitoring </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"You are working day shift at an urban tertiary centre and have been asked to review a Cat 2 48-year-old female who presented with epigastric pain, coffee ground vomitus & pre-syncope. The patient is known to have Hepatitis C & ETOH dependence. She has just had an episode of fresh haematemesis in resus with estimated volume of 250mls. The patient is in the resus bay on full monitoring and has two 18G IVCs already inserted. The following vitals are recorded:\n\nGCS\n\nHR\n120\n\nBP\n100/60\n\nT\n37.3°C","parts":[{"id":"a","label":"Part A","prompt":"List (4) medications with dose & rationale that you would prescribe this patient whilst in ED (8 marks) Medication Rationale The patient subsequently has a further bout of large volume haematemesis in the resus bay. Updated vitals are now: GCS 12 HR 140 BP 80/45 RR 28 Sats 90% on 6L/min O2"},{"id":"b","label":"Part B","prompt":"State your NEXT STEPS in management (4 marks)"},{"id":"c","label":"Part C","prompt":"Aside from age > 65, name the (4) other components of the AIMS-65 score for prognosis in upper GI bleeding (4 marks)"},{"id":"d","label":"Part D","prompt":"What is the estimated in-hospital mortality for an AIMS-65 score of 4? (1 mark) The patient had presented and was discharged from ED multiple times in the prior year with minor issues related to alcohol use."},{"id":"e","label":"Part E","prompt":"Name an intervention performed during these visits that may have assisted in reducing longer term alcohol-related harm in this patient. (1 mark)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Ceftriaxone 1-2g IV</td><td>Reduced infection in variceal bleed</td></tr><tr><td>Fentanyl 25-50mcg IV</td><td>Analgesia / abdo pain</td></tr><tr><td>Octreotide 50mcg IV + infusion or</td><td>Reduce splanchnic blood flow</td></tr><tr><td colspan=\"2\">Terlipressin 2mg IV Q4h</td></tr><tr><td>Metoclopramide 10mg IV or</td><td>Antiemetic / prokinetic for better view at</td></tr><tr><td>erythromycin 250mg</td><td>endoscopy</td></tr><tr><td>Thiamine 300-500mg IV</td><td>ETOH thiamine deficiency / Wernicke’s</td></tr><tr><td colspan=\"2\">prophylaxis</td></tr><tr><td>Pantoprazole 40-80mg IV (infusion ok)</td><td>Reduce gastric acid (though limited evidence)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">1. Supplemental O2 NRBM 15L/minO2 &amp; rapid preparation to secure airway (noting</div><div class=\"answer-line\">high risk intubation, ensure double suction set-up and PPE for all)</div><div class=\"answer-line\">2. Commence O negative blood/ MTP via large IVC; aim MAP &gt; 60-65 (permissive</div><div class=\"answer-line\">hypotension). <em>No mark if crystalloid given</em></div><div class=\"answer-line\">3. Check BSL, replace 25-50mls 50% dextrose aim BSL &gt; 4 (note lower GCS in stem)</div><div class=\"answer-line\">4. Arrange urgent gastroenterology / anaesthetics review to facilitate endoscopy</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">1. Albumin &lt; 30g/L</div><div class=\"answer-line\">2. INR &gt; 1.5</div><div class=\"answer-line\">3. Altered mental state</div><div class=\"answer-line\">4. SBP &lt; 90</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">16.5% (accept 12-20%)</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Alcohol screening &amp; brief intervention eg AUDIT-C (other acceptable answers, but would</div><div class=\"answer-line\">not accept D&amp;A referral alone)</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A usually fit and well 20-month-old baby arrives by ambulance with a one-day history of\nlethargy. On arrival she is noted to be tachycardic. You obtain and ECG :","parts":[{"id":"a","label":"Part A","prompt":"State the arrhythmia and (4) supportive findings. (3 marks) The baby is moved to resus for further assessment."},{"id":"b","label":"Part B","prompt":"What features on clinical examination suggest shock? (3 marks) You determine that the baby is haemodynamically stable."},{"id":"c","label":"Part C","prompt":"List the steps involved in eliciting the dive reflex in a 20-month-old. (4 marks)"},{"id":"d","label":"Part D","prompt":"Unfortunately, this was not successful. What are two considerations when using adenosine in this patient? (2)"}],"propPages":["asset:img854c51413c4456f446"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">(1 mark for SVT and 0.5 each for supportive findings)</div><div class=\"answer-line\">Arrhythmia = SVT</div><div class=\"answer-line\">· Rate 300</div><div class=\"answer-line\">· Narrow complex</div><div class=\"answer-line\">· Fixed rate/regular – not variable</div><div class=\"answer-line\">· Absent p waves or p waves after the QRS or P wave inversion II, III, aVF</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Pale/mottled skin/central cap refill time &gt;5 sec</div><div class=\"answer-line\">Lethargy/irritability/drowsiness</div><div class=\"answer-line\">Tachypnoea</div><div class=\"answer-line\">Weak pulse, hypotension (late sign)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">· Explain to caregivers what you are going to do</div><div class=\"answer-line\">· Ensure cardiac monitoring and pads on</div><div class=\"answer-line\">· IV access prior (can sometimes revert SVT)</div><div class=\"answer-line\">· Apply cold pack (eg. ice slurry in pathology bag or ice cold washer) to face – covering</div><div class=\"answer-line\">mouth and nose – for 15 seconds.</div><div class=\"answer-line\">· Can repeat a second time if unsuccessful</div><div class=\"answer-line\">ICE WATER IMMERSION NOT APPROPRIATE FOR &gt;6 MONTHS – TOO DISTRESSING</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">· Allergic reaction</div><div class=\"answer-line\">· Beware of adenosine changing re-entry SVT to atrial fibrillation, which can be</div><div class=\"answer-line\">dangerous if WPW is present. This will require DC cardioversion.</div><div class=\"answer-line\">· Rapid re-initiation of tachycardia is not uncommon, mostly due to premature atrial</div><div class=\"answer-line\">contractions stimulated by the adenosine. If this occurs, discuss with Cardiology</div><div class=\"answer-line\">· (Rarely) atrial fibrillation or prolonged pauses may occur</div><div class=\"answer-line\">· Undiagnosed qdenosine-deaminase deficiency (rare immune deficiency)</div><div class=\"answer-line\">Stuff about kids on theophylline, hx asthma/bronchospasm/cardiac transplant not</div><div class=\"answer-line\">relevant in THIS patient</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 32-year-old female is referred to ED by her GP with hypertension. She has been\nexperiencing progressive dizziness, headache & lethargy for one month. Her only past medical history includes pre-eclampsia 4 years ago. She is not on any regular medications, does not smoke, drink alcohol or use illicit drugs. Vitals measured on ED arrival as follows :\n\nGCS\n\nHR\n120\n\nBP\n255 / 155\n\nRR\n\nSats\n98%, RA\n\nTemp 37.4\nUrine demonstrates moderate blood & protein, nil leucocytes or nitrites. BHCG is negative.","parts":[{"id":"a","label":"Part A","prompt":"Define hypertensive emergency (1 mark)"},{"id":"b","label":"Part B","prompt":"List (5) specific causes of secondary hypertension that may result in hypertensive emergency (5 marks) Initial blood results return as follows:"},{"id":"c","label":"Part C","prompt":"What is the most likely haematologic diagnosis to account for these results? (1 mark)"},{"id":"d","label":"Part D","prompt":"State (1) other haematological investigation result to support this diagnosis (1 mark) The patients BP does not respond to oral medications given on arrival."},{"id":"e","label":"Part E","prompt":"List (4) specific drug infusion options for IV treatment of hypertensive emergency with an appropriate infusion dose/rate (4 marks)"}],"propPages":["asset:imgebe4ed1953769ebde6"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Severe hypertension (BP &gt; 220/ 140) with evidence of end organ damage or dysfunction</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Renovascular disease eg renal artery stenosis</td></tr><tr><td></td><td>Primary Kidney disease eg glomerulonephritis</td></tr><tr><td></td><td>Hyperaldosteronism</td></tr><tr><td></td><td>Cushings syndrome</td></tr><tr><td></td><td>Sleep apnoea</td></tr><tr><td></td><td>Phaeochromacytoma</td></tr><tr><td></td><td>Drug induced eg contraceptives, anabolic steroids, NSAIDs, stimulants</td></tr><tr><td colspan=\"2\">Hypo/hyperthyroidism</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Microangiopathic haemolytic anaemia (MAHA)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Blood film - Schistocytes</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Labetalol 20-40mg push then infusion 20mg/hr up to maximum 160mg/hr</td></tr><tr><td></td><td>Esmolol 500mcg/kg over 1 minute then 50-200mcg/kg/min</td></tr><tr><td></td><td>Glyceryl trinitrate 10mcg/min up to 100mcg/min (increasing by 5mcg/min)</td></tr><tr><td></td><td>Clevidipine 1-2mg/hr doubling every 90 seconds until BP target achieved</td></tr><tr><td colspan=\"2\">Sodium Nitroprusside 0.3mcg/kg/min up to 10mcg/kg/min</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 26-year-old female has been brought into the ED by her friend post an alleged assault by her partner. The patient is unable to recall events. On initial inspection you note some bruising to her neck and are concerned she may have been a victim of nonfatal strangulation.","parts":[{"id":"a","label":"Part A","prompt":"List (6) facial/cranial/neurological red flags for potential serious underlying injury you would seek in your assessment. (6 marks)"},{"id":"b","label":"Part B","prompt":"Give (2) radiological tests you might order with justification for each. (2 marks)\nThe patient says she has a 4-year-old son, currently with her partner, whom thinks\nwitnessed the incident. She is worried about his safety."},{"id":"c","label":"Part C","prompt":"List key steps in managing this situation. (2 marks) The patient undergoes imaging which does not demonstrate any significant injuries."},{"id":"d","label":"Part D","prompt":"State factors that would influence your decision to observe / admit the patient vs discharge them home. (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>No points for amnesia or neck bruises given in stem</em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Non contrast CTB and CT arch to COW – assess for features of carotid or vertebral artery</td><td>dissection or ischaemic/watershed/haemorrhagic stroke</td></tr><tr><td>CT cervical spine and soft tissue – if unable to clinically clear C-spine, evidence of neck</td><td>swelling, ligature marks, dysphonia, dyspnoea</td></tr><tr><td>CT chest – subcutaneous emphysema or dyspnoea</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">2. Notify on-call social worker</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">1. Consider admission/observation if the patient presents very soon after the incident</div><div class=\"answer-line\">2. If patient had ongoing symptoms or a significant blunt force trauma mechanism they</div><div class=\"answer-line\">should be admitted for observation</div><div class=\"answer-line\">3. Admit / observe if no safe discharge destination available, particularly after hours</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 2-year-old boy is brought to your Emergency Department not weight-bearing on his left leg. This has been noted for the past 5 days and he seems to be progressively more reluctant to walk. He is otherwise well with no past medical history and immunisations are UTD. Vitals are : T 38.5°C HR 150 RR 30 Sats 99%RA","parts":[{"id":"a","label":"Part A","prompt":"List (5) potential causes for this boy’s signs and symptoms. (5 marks) X-ray of the L ankle is performed and shown below :"},{"id":"a2","label":"Part A","prompt":"List (3) relevant findings and state a conclusion. (4 marks)"},{"id":"b","label":"Part B","prompt":"List (3) further investigations you would order and provide rationale for each. (3 marks)"}],"propPages":["asset:imgf3f21c11e00a23edd3"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Toddlers spiral fracture</div><div class=\"answer-line\">Acute viral induced myositis</div><div class=\"answer-line\">Rarer differentials : malignancy eg Ewing’s sarcoma, post infectious arthritis, HSP</div></section><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>Bony erosion of the distal medial aspect of the tibia with a moth-eaten appearance </strong></div><div class=\"answer-line\">Slight thickening to the edges of the bone</div><div class=\"answer-line\">No fracture</div><div class=\"answer-line\">No joint effusion</div><div class=\"answer-line\"><strong>Conclusion : likely osteomyelitis</strong> (ddx malignancy)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>Raised WCC, platelets as inflammatory markers</td><td></td></tr><tr><td>CRP</td><td>Significant elevation may suggest bacteraemia, trend will enable</td></tr><tr><td>monitoring of recovery</td><td></td></tr><tr><td>Blood cultures</td><td>To exclude bacteraemia as trigger for septic arthritis, direct</td></tr><tr><td>antibiotic therapy</td><td></td></tr><tr><td>Blood film</td><td>If concern for haematological malignancy</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"A 35-year-old woman with a history of depression, T2DM, iron deficiency anaemia and\npolycystic ovarian syndrome, is brought to ED by the community mental health team after she admitted to taking a drug overdose 24 hours prior. She complains of generalised abdominal pain, nausea and vomiting. Vitals on arrival :\n\nRR\n\nSpO2 92% on RA\n\nHR\n120 bpm\n\nBP\n76/35 mmHg\n\nGCS\n13 (E3 V4 M6 progressive confusion) She is brought straight to the resus bay and placed on appropriate monitoring. IV accessed is\n• btained. Results of her initial VBG are shown below :\n\npH\n6.9\n\npCO2\n\nHCO3\n\nLactate\n\nGlucose\n6.5\n\nNa\n145\n\nCl\n\nK\n5.0\n\nUrea\n\nCreatinine\n289","parts":[{"id":"a","label":"Part A","prompt":"Identify (2) important acid/base abnormalities in this patient providing calculations for each (4 marks)"},{"id":"b","label":"Part B","prompt":"What is the most likely diagnosis? Provide justification. (2 marks)"},{"id":"c","label":"Part C","prompt":"Give (3) other toxicological differentials with a distinguishing clinical feature for each. (3 marks)"},{"id":"d","label":"Part D","prompt":"What are the indications for dialysis? (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>Anion Gap = Na-(HCO3+Cl) = 145 – (6+99) = 40</strong></td><td></td></tr><tr><td></td><td>Inadequate respiratory compensation (or concurrent respiratory acidosis)</td></tr><tr><td>Expected PCO2 = 1.5 x HCO3 + 8 (+/-2) = 1.5 x 6 + 8 = 17</td><td></td></tr><tr><td><em>Could calculate delta gap/ratio but AG and Winter’s formula most relevant</em></td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Metformin (MALA) : profound hyperlactaemia, patient has PCOS so likely to have been</div><div class=\"answer-line\">prescribed metformin to manage related metabolic issues, XR formulation would give</div><div class=\"answer-line\">onset of toxicity &gt;6-12 hours</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Salicylate : mixed resp alkalosis + HAGMA, altered mental state -&gt; seizures</td><td>Iron : haemorrhagic gastroenteritis, multi-organ failure</td></tr><tr><td>Ethylene glycol : raised osmolar gap, hypocalcaemia, Ca oxalate crystals in urine</td><td>Methanol : raised osmolar gap, visual changes</td></tr><tr><td>Paracetamol : fulminant hepatic failure</td><td>Isoniazid : rapid neurological deterioration with seizures/coma within 2 hours of</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Severe metabolic acidosis (pH &lt; 7.0 or serum lactate &gt; 20mmol/L)</div><div class=\"answer-line\"></div><div class=\"answer-line\">Refractory hypotension unresponsive to fluids/vasopressors</div><div class=\"answer-line\"></div><div class=\"answer-line\">Rapid deterioration and AKI with rising Cr</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 43-year-old male is brought into ED following an out-of-hospital respiratory arrest. He has a history of polysubstance abuse, schizophrenia and is morbidly obese (160kg, BMI 50). He was found by a family member cyanosed with ineffective breathing and bystander CPR was commenced until the retrieval team arrived. He arrives intubated and manually ventilated with vital signs: RR 20, SpO2 75% on 100% O2 (PEEP 5), BP 95/50, HR 130, temp 36.9C. The retrieval team describe a challenging prehospital resuscitation with long scene time, poor laryngoscopic view (grade 3), multiple attempts at laryngoscopy, difficult oxygenation and difficult manual ventilation.","parts":[{"id":"a","label":"Part A","prompt":"Complete the table below listing (6) possible causes of the patient’s hypoxia and an intervention you would perform to address each cause. Cause of hypoxia Intervention After some interventions to stabilize oxygenation and ventilation, you are ready to establish the patient on the ventilator."},{"id":"c","label":"Part C","prompt":"List (3) modifications you would make to standard ventilatory parameters in a bariatric patient along with a rationale for each (6 marks) Modification to ventilation Rationale"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">A 43-year-old male is brought into ED following an out-of-hospital respiratory arrest. He has a</div><div class=\"answer-line\">history of polysubstance abuse, schizophrenia and is morbidly obese (160kg, BMI 50). He was</div><div class=\"answer-line\">found by a family member cyanosed with ineffective breathing and bystander CPR was</div><div class=\"answer-line\">commenced until the retrieval team arrived.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Set tidal volume at 6-8 ml/kg of <strong>ideal body </strong></td><td>Tidal volumes based on <em>actual</em> body weight</td></tr><tr><td><strong>weight </strong></td><td>are too high and may cause barotrauma</td></tr><tr><td><strong>Increase Pmax</strong> above default setting</td><td>Avoid pressure limit cutoff and insufficient TV</td></tr><tr><td>(&gt;35cmH2O) to optimise tidal volumes</td><td>caused by upper airways resistance. NB-Still</td></tr><tr><td>need to ensure plateau pressure remains</td><td></td></tr><tr><td>&lt;30cmH2O to avoid barotrauma.</td><td></td></tr><tr><td>Anticipate needing <strong>higher PEEP</strong> (&gt;10cmH2O)</td><td>Obese patients more prone to atelectasis in</td></tr><tr><td>for oxygenation</td><td>supine position, may need higher PEEP to</td></tr><tr><td>recruit</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"You are working in a regional ED when parents present with a 4-day-old boy with PR bleeding. The neonate was an uncomplicated delivery at term, APGARS 9 and 9, birth weight 3kg. Discharged day 2 of life. There was blood in the stool yesterday but worsening today with a moderate amount of fresh blood seen in the nappy. On examination :\n\nCap refill\n3 seconds\n\nHR\n127\n\nBP\n79/44\n\nRR\n\nSats\n98% RA\n\nTemp\n35.9 ̊C Initial bloods :\n\nHb\n120 q g/L\n\nWCC\n9.7\n\nPlatelets\n190 PT >150\n\nINR\n>10\n\nAPTT\n109 (normal)","parts":[{"id":"a","label":"Part A","prompt":"What is the MOST LIKELY diagnosis? (1 mark)"},{"id":"b","label":"Part B","prompt":"Give (2) differentials for PR bleeding in the first week of life (2 marks)"},{"id":"c","label":"Part C","prompt":"List (3) pertinent findings you would seek on examination. (3 marks)"},{"id":"d","label":"Part D","prompt":"What treatment would administer for this condition? (2 marks)"},{"id":"e","label":"Part E","prompt":"What further investigation is warranted/indicated in this patient? (1 mark) Following treatment, repeat INR remains greater than 10."},{"id":"f","label":"Part F","prompt":"What are your next steps/priorities/management? (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Haemorrhagic disease of the newborn (or vitamin K deficiency bleeding VKDB)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Swallowed maternal blood</div><div class=\"answer-line\">Anal fissure</div><div class=\"answer-line\">Allergic protocolitis (milk protein allergy)</div><div class=\"answer-line\">Bowel polyp/haemangioma</div><div class=\"answer-line\">Infectious colitis</div><div class=\"answer-line\">NEC</div><div class=\"answer-line\">Haemophilia (rare)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Bruising/petechiae</div><div class=\"answer-line\">Umbilical stump bleeding</div><div class=\"answer-line\">Mucosal bleeding from nose/mouth</div><div class=\"answer-line\">Irritability/bulging fontanelle – to suggest intracranial bleed</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Vitamin K 1mg IV</div><div class=\"answer-line\">FFP 10 to 20ml/kg IV</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Head ultrasound to assess further bleeding</div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\">Repeat vitamin K 1mg after 4 to 6 hours</div><div class=\"answer-line\">Repeat 10ml/kg of FFP IV</div><div class=\"answer-line\">Arrange retrieval to neonatal intensive care unit</div><div class=\"answer-line\">Screen for liver disease</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 41-year-old woman (G1P1) presents 4 days postpartum with headache, nausea and\nvomiting.","parts":[{"id":"a","label":"Part A","prompt":"Provide (6) possible differentials in the table below with (2) key assessment findings and (2) specific management options for each. Drug doses not required. (18 marks) Differential\nKey assessment findings x 2 (1/2\nSpecific management options x Diagnosis (1 mark) mark each) 2 (1/2 mark each)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>Diagnosis (1 mark)</strong></td><td><strong>mark each)</strong> <strong>2 (1/2 mark each)</strong></td></tr><tr><td><strong>Preclampsia</strong></td><td>Persistent BP &gt;140/90 IV MgSO4 LD then infusion</td></tr><tr><td><strong>(must have)</strong></td><td>Neuro symptoms eg. visual disturbance, Antihypertensives eg. IV</td></tr><tr><td>hyperreflexia</td><td>labetalol/hydralazine)</td></tr><tr><td>Proteinuria</td><td></td></tr><tr><td>HELLP syndrome blood abnormalities</td><td></td></tr><tr><td><strong>CVST</strong></td><td>Progressive headache Anticoagulation (LMWH or UFH</td></tr><tr><td>Seizures</td><td>infusion)</td></tr><tr><td>AMS</td><td>Seizure management</td></tr><tr><td>Focal neuro deficit</td><td>(leviteracetam)</td></tr><tr><td>Filling defect on CT venogram</td><td>ICP management</td></tr><tr><td>Endovascular therapy for severe or</td><td></td></tr><tr><td>refractory cases</td><td></td></tr><tr><td><strong>Post dural puncture </strong></td><td>History of epidural or spinal anaesthesia Strict bed rest and hydration</td></tr><tr><td><strong>headache</strong></td><td>Headache worse with sitting up, relieved Caffeine</td></tr><tr><td>lying flat</td><td>Blood patch if severe</td></tr><tr><td><strong>Migraine (or other </strong></td><td>Prior history, same as previous episodes Dopamine agonists eg.</td></tr><tr><td><strong>primary headache)</strong></td><td>Usually unilateral, pulsatile prochlorperazine, chlorpromazine</td></tr><tr><td>Photophobia, phonobia</td><td>Triptans</td></tr><tr><td>History of aura</td><td></td></tr><tr><td><strong>Posterior Reversible </strong></td><td>Associated with preeclampsia/eclampsia Targeted BP control : 20-25%</td></tr><tr><td><strong>Encephalopathy </strong></td><td>Severe headache, confusion, cortical reduction in MAP first few hours</td></tr><tr><td>blindness</td><td>&lt;140/90 in most patients with IV</td></tr><tr><td><strong>Syndrome (PRES)</strong></td><td></td></tr><tr><td>Seizures, encephalopathy</td><td>antiHT</td></tr><tr><td>MRI hyperintensities in parieto-occipital</td><td>Seizure management</td></tr><tr><td>regions</td><td>(leviteracetam)</td></tr><tr><td><strong>SAH</strong></td><td>Thunderclap headache Targeted BP control as above</td></tr><tr><td>Signs of meningism</td><td>Nimodipine</td></tr><tr><td>Subarachnoid blood on CTB or high</td><td>Neurosurgical consult for</td></tr><tr><td>RCC/xanthochromia on LP</td><td>clipping/coiling</td></tr><tr><td><strong>Pituitary apoplexy </strong></td><td>History of PPH IV hydrocortisone (+other hormone</td></tr><tr><td><strong>(Sheehan’s </strong></td><td>Bitemporal hemianopia replacement)</td></tr><tr><td>Failure to lactate (PRL deficiency)</td><td>Neurosurgery/endocrine consult</td></tr><tr><td><strong>Syndrome</strong></td><td></td></tr><tr><td>Adrenal insufficiency eg. hypotension,</td><td></td></tr><tr><td>hypoNa, hypoglycaemia</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"You are the ED consultant in a metropolitan tertiary hospital. A nurse has asked you to urgently review a 51-year-old female who has been triaged as a Category 2 to the resuscitation bay. She appears critically unwell. She speaks no English, and limited collateral history is provided by an acquaintance. She is visiting from China and arrived 10 days ago. She has had profuse diarrhoea, vomiting, worsening lethargy, and increasing shortness of breath over the past 3 days.\n\nVital signs :\n\nTemp 37.4°C\n\nHR\n150\n\nBP\n100/50\n\nRR\n\nSaO2 unobtainable\n\nGCS 12\nAn ABG is performed and shown below :","parts":[{"id":"a","label":"Part A","prompt":"Give (3) relevant equations and an interpretation for each (6 marks) Equation Interpretation"},{"id":"b","label":"Part B","prompt":"List (4) other investigations you would order with a rationale for each. (4 marks)"},{"id":"c","label":"Part C","prompt":"Outline your treatment priorities in the first hour including drug doses/routes where relevant. (4 marks)"},{"id":"d","label":"Part D","prompt":"List and address (4) barriers to culturally safe care in the ED for CALD patients. (4 marks) Barrier Strategy to address"}],"propPages":["asset:imgafffc6a5828617fa8d"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>AG = Na – (HCO3 + Cl)</td><td><strong>Profound acidosis HAGMA (likely DKA with </strong></td></tr><tr><td>= 139 – (1.6 + 113)</td><td><strong>lactic acidosis from hypoperfusion)</strong></td></tr><tr><td>= 24.4</td><td></td></tr><tr><td>Delta gap = ΔAG – ΔHCO3</td><td><strong>Negative suggesting concomitant NAGMA </strong></td></tr><tr><td>= (24.4-12) – (24-1.6) = 12.4 – 22.4 = -10</td><td><strong>secondary to profuse diarrhoea</strong></td></tr><tr><td>Expected CO2 = 1.5 x HCO3 + 8 = 10.4</td><td>Actual CO2 17 therefore inadequate respiratory</td></tr><tr><td>compensation -&gt; concurrent respiratory acidosis</td><td></td></tr><tr><td>Corrected K = measured K - 0.6 per 0.1 drop in</td><td>Profound total body potassium depletion despite</td></tr><tr><td>pH</td><td>normokalaemia</td></tr><tr><td>= 3.5 – 0.6 (7.4-6.8) x 10 = 0.1</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td>ECG  : characterise significant tachycardia ?AF/flutter/SVT</td><td>Serum/urine ketones : confirm DKA, monitor for clearance</td></tr><tr><td>Stool MCS – identify infective cause of diarrhoea,  exclude bacterial gastroenteritis</td><td>CXR : evaluate for aspiration, pneumonia or other pulmonary pathology contributing to</td></tr><tr><td>dyspnoea</td><td>CTB : if no improvement in GCS from resuscitative measures</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>Fluid resuscitation </strong>: IV crystalloid 1L over 1hr; reassess perfusion and repeat +/- vasopressor</div><div class=\"answer-line\">if hypotensive post-volume</div><div class=\"answer-line\"><strong>Aggressive potassium replacement </strong>: initiate before insulin, 40-60mmol/L/hr via central</div><div class=\"answer-line\">access with careful monitoring and IV MgSO4</div><div class=\"answer-line\"><strong>Treat ketoacidosis</strong>:  Fast acting insulin infusion 0.1U/kg/hr (Actrapid / Novorapid)</div><div class=\"answer-line\">Respiratory support : HFNC FiO2 titrated to Sats &gt; 92% increasing flow rate as high as patient</div><div class=\"answer-line\">can tolerate <em>(reduces deadspace and WOB)</em></div><div class=\"answer-line\">Treat vomiting : Ondansetron 4-8mg IV / metoclopramide 10mg IV</div><div class=\"answer-line\"><em><strong>NO MARKS FOR INTUBATION unless appropriate indication stated.  Want to avoid this </strong></em></div><div class=\"answer-line\"><em><strong>where possible – mental status should improve over time with resuscitation</strong></em></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Language barriers</td><td>Access to 24hr phone/video interpreter</td></tr><tr><td colspan=\"2\">Avoid reliance on family members for interpretation</td></tr><tr><td colspan=\"2\">Provide written material in patient’s primary language</td></tr><tr><td colspan=\"2\">where possible</td></tr><tr><td>Cultural misunderstanding or</td><td>Provide culturally safe training for ED staff</td></tr><tr><td>assumptions</td><td>Encourage reflective practice and awareness of</td></tr><tr><td colspan=\"2\">clinician bias</td></tr><tr><td>Concerns about cost or insurance</td><td>Involve social work and finance teams early</td></tr><tr><td colspan=\"2\">Explain rights to emergency care irrespective of</td></tr><tr><td colspan=\"2\">Medicare status</td></tr><tr><td>Fear or mistrust of hospitals or authority</td><td>Engage hospital cultural liaison officers</td></tr><tr><td>figures</td><td>Build rapport through trauma-informed</td></tr><tr><td colspan=\"2\">communication</td></tr><tr><td>Low health literacy or unfamiliarity with</td><td>Use plain English</td></tr><tr><td>the Australian healthcare system</td><td>Explain ED processes (eg. triage, investigations,</td></tr><tr><td colspan=\"2\">discharge plans</td></tr><tr><td colspan=\"2\">Consider follow-up support or written discharge</td></tr><tr><td colspan=\"2\">information in first language</td></tr><tr><td>Gender-specific concerns (eg. preference</td><td>Offer access to same gender medical and nursing staff</td></tr><tr><td>for same-gender clinician during intimate</td><td>when feasible</td></tr><tr><td>exams)</td><td>Ensure privacy and respectful explanations of</td></tr><tr><td colspan=\"2\">necessity of care</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A 55-year-old woman is brought into ED by ambulance with sudden onset headache, vomiting\nand progressive decrease in level of consciousness. She has a background history of atrial fibrillation, TIA and type 2 diabetes mellitus. Her vitals are :\n\nRR\n\nSats\n95%RA\n\nHR\n\nBP\n225/117\n\nGCS\nE2V3M4 = 9 A CT brain is performed :","parts":[{"id":"a","label":"Part A","prompt":"State (3) important findings on the above CT image. (3 marks)"},{"id":"b","label":"Part B","prompt":"List (3) risk factors for this condition. (3 marks)"},{"id":"c","label":"Part C","prompt":"Outline (6) key management priorities. Provide drug dose/route/rate where applicable (6 marks)"}],"propPages":["asset:img08783768faa10158a9"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">R cerebellar hemisphere haemorrhage</div><div class=\"answer-line\">Medial extension involving 4th ventricle with perilesional oedema</div><div class=\"answer-line\">Dilatated temporal horns of lateral ventricles suggestive of obstructive hydrocephalus</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Hypertension</div><div class=\"answer-line\">Underlying vascular lesion eg. AVM, aneurysm, dural AV fistula</div><div class=\"answer-line\">Haemorrhagic transformation of ischaemic infarct</div><div class=\"answer-line\">Other : amyloid angiopathy, brain tumour</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>Airway protection </strong>: neuroprotective intubation to prevent aspiration and secondary</div><div class=\"answer-line\">brain injury</div><div class=\"answer-line\"><strong>Targeted BP control to 140-180mmHg</strong> : arterial line, IV labetalol 20mg over 1-2 minutes</div><div class=\"answer-line\">q10min to max 300mg -&gt; infusion OR hydralazine 10mg slow IV push q15min OR</div><div class=\"answer-line\">clevidipine infusion if available</div><div class=\"answer-line\"><strong>General ICP management</strong> : 30 deg head up, secure ETT with tape (avoid ties), maintain</div><div class=\"answer-line\">to low normal PCO2, adequate sedation/paralysis, antiemetic, IDC</div><div class=\"answer-line\"><strong>Reverse anticoagulation (likely on DOAC) : </strong> 4-factor PCC or FFP + prothrombinex if</div><div class=\"answer-line\">available (adnexanet alfa if available and criteria met)</div><div class=\"answer-line\"><strong>Acute ICP control if signs of herniation</strong> : hyperventilation + osmotherapy (hypertonic</div><div class=\"answer-line\">saline 3% 3ml/kg over 10-15min OR mannitol 1g/kg over 10 minutes)</div><div class=\"answer-line\"><strong>Urgent neurosurgical referral</strong> : consideration of decompressive craniectomy</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"A 75-year-old woman presents to ED with right loin pain and rigors. She has a past history of type 2 diabetes and hypertension for which she takes regular metformin, gliclazide, ramipril and amlodipine.\nHer vital signs are:\n\nHR\n102\n\nBP\n90/60\n\nRR\n\nSaO2\n95% RA\n\nTemp\n39°C Her CT KUB is shown below :","parts":[{"id":"a","label":"Part A","prompt":"List (4) abnormalities visible on this CT scan (4 marks) and provide a unifying diagnosis (1 mark)"},{"id":"b","label":"Part B","prompt":"Outline your management priorities for this patient. (4 marks) The patient develops acute severe kidney injury with oliguria."},{"id":"c","label":"Part C","prompt":"List (3) complications you would monitor for in this patient (3 marks)"}],"propPages":["asset:img86973dc05d4fe03db7"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Extensive peri-renal stranding R&gt;L</div><div class=\"answer-line\"><strong>2.</strong></div><div class=\"answer-line\">Stone in right renal pelvis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><strong>Urgent urology review</strong> for surgical decompression of kidney with either</td></tr><tr><td colspan=\"2\">nephrostomy or JJ stent</td></tr><tr><td><strong>2.</strong></td><td><strong>Broad spectrum antibiotic cover</strong>: IV amoxicillin/ampicillin 2g plus gentamicin 5-</td></tr><tr><td colspan=\"2\">7mg/kg OR Tazocin 4.5g acceptable</td></tr><tr><td><strong>3.</strong></td><td><strong>Haemodynamic resuscitation </strong>: crystalloid bolus (10mL/kg) reassess and repeat</td></tr><tr><td colspan=\"2\">aiming for MAP &gt;65mmHg, early use of vasopressors if persistent/worsening</td></tr><tr><td colspan=\"2\">hypotension</td></tr><tr><td><strong>4.</strong></td><td><strong>Analgesia</strong> – safe agents, e.g. IV fentanyl 25-50mcg, paracetamol. NSAIDs not ideal.</td></tr><tr><td colspan=\"2\">(Will need HDU/ICU-level care due to risks of progressive septic shock, likely needing</td></tr><tr><td colspan=\"2\">vasopressors)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Metformin-related <strong>lactic acidosis</strong></div><div class=\"answer-line\"><strong>3.</strong></div><div class=\"answer-line\"><strong>Hypoglycaemia</strong> due to renal accumulation of gliclazide</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"You have been asked to write a management plan for a 35-year-old male who has become a frequent presenter to your ED with back pain. There have been several incidents of aggressive behaviour involving this man, requiring his removal by security. The ED nurse manager suspects that he is seeking opiates.","parts":[{"id":"a","label":"Part A","prompt":"List (6) elements of the patient’s history that would be suspicious for drug-seeking behaviour. (6 marks)"},{"id":"b","label":"Part B","prompt":"State (6) pieces of information that you would include in this patient’s ED management plan (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">History of IVDU / treatment for opiate addiction</div><div class=\"answer-line\">Multiple recent ED presentations for similar somatic complaints, often no clear</div><div class=\"answer-line\">underlying diagnosis</div><div class=\"answer-line\">Doctor shopping / using multiple providers</div><div class=\"answer-line\">Repeated reports of lost or stolen medications</div><div class=\"answer-line\">Request for specific opioids by name and dose</div><div class=\"answer-line\">Claims of allergies to non-opioid analgesics</div><div class=\"answer-line\">Vague, inconsistent or dramatic histories with lack of objective signs</div><div class=\"answer-line\">Anger or irritability when questioned about reasons for ED presentation</div><div class=\"answer-line\">Refusal of diagnostic workup or physical examination / focus on obtaining pain relief</div><div class=\"answer-line\">rather than investigating cause of pain</div><div class=\"answer-line\">Frequently self-discharges after receiving opiates / history of absconding with IV cannula</div><div class=\"answer-line\">in situ</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>Presenting complaint pattern</strong> : description of typical back pain, frequency of</div><div class=\"answer-line\">presentations, chronic vs medically unexplained</div><div class=\"answer-line\">Summary of previous workup and findings, state if no ongoing organic cause found</div><div class=\"answer-line\">History of opioid use and request : past prescriptions, sources, medication-seeking</div><div class=\"answer-line\">behaviour</div><div class=\"answer-line\">Past history, D+A and forensic history, medication allergies and intolerances</div><div class=\"answer-line\">Behavioural concerns or ED interactions : include incidents of aggression, manipulation</div><div class=\"answer-line\">or refusal of care, security involvement, resolution</div><div class=\"answer-line\">External providers or services involved : GP and practice (if known), addiction</div><div class=\"answer-line\">medicine/pain clinic</div><div class=\"answer-line\"><strong>Plan for medical assessment : early review by senior doctor</strong></div><div class=\"answer-line\"><strong>Plan for pain relief</strong> : offer multimodal non-opioid analgesia in the first instance</div><div class=\"answer-line\">emphasising return to function, not elimination of pain</div><div class=\"answer-line\">Plan for dealing with aggression : adoption of trauma informed, nonjudgemental</div><div class=\"answer-line\">language whilst setting boundaries</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"A 75-year-old man with a history of atrial fibrillation, presents with severe left leg and groin pain. On examination the leg is cold, and pulses are not palpable. 7 days ago he underwent a balloon angioplasty of his left popliteal artery.","parts":[{"id":"a","label":"Part A","prompt":"What features on bedside assessment would make you suspicious for a pseudoaneurysm of the femoral artery? (3 marks)"},{"id":"b","label":"Part B","prompt":"Besides pseudoaneurysm, what are (6) other LOCAL complications following femoral artery puncture for angiography. (6 marks) The patient’s discharge summary records a normal ankle-brachial pulse index (ABPI)."},{"id":"c","label":"Part C","prompt":"What ABPI value would now make you concerned for leg ischaemia? (1 mark) The vascular team want to take patient to theatre. You note that he restarted his anticoagulation two days ago."},{"id":"d","label":"Part D","prompt":"What are (2) indications for the use of Andexanet Alfa (‘Andexxa’)? (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Painful mass over femoral artery</div><div class=\"answer-line\">Pulsatile</div><div class=\"answer-line\">US findings demonstrate contained rupture into one of the arterial wall layers</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Vessel occlusion – resulting in ischaemic limb downstream</div><div class=\"answer-line\">Haematoma – non-pulsatile, dx on US</div><div class=\"answer-line\">AV fistula</div><div class=\"answer-line\">DVT secondary to femoral venous compression from local swelling</div><div class=\"answer-line\">Haemorrhage from puncture site</div><div class=\"answer-line\">Infection at puncture site</div><div class=\"answer-line\">Femoral nerve injury</div><div class=\"answer-line\">Local extravasation of contrast</div><div class=\"answer-line\">NOT: contrast allergy/nephropathy/PE/AMI/stroke/systemic sepsis etc as not local</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">&lt;0.5</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Patient is taking a Xa inhibitor (apixaban or rivaroxaban)</div><div class=\"answer-line\">They have life-threatening haemorrhage e.g. ICH</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"You are the consultant working in a mixed paed/adult Emergency Dept when the triage nurse alerts you to the arrival of a 15-month-old boy with lethargy & vomiting. The child was found in the back seat of a car at the local shopping centre car park. Outside temperature is 38°C. The child is moved straight into the resuscitation area and monitoring is placed. Vital signs are recorded as follows\n\nTemp (tympanic)\n40.6C\n\nHR\n170bpm\n\nBP\n60/40\n\nRR\n\nSaO2\n90% on RA P on AVPU scale","parts":[{"id":"a","label":"Part A","prompt":"List (2) physiological characteristics of children which make them more susceptible to heat-related illness compared with adults. (2 marks) Intravenous access is obtained and initial resuscitation has commenced"},{"id":"b","label":"Part B","prompt":"Prioritise a list of (3) methods you would use to rapidly cool this child. (3 marks)"},{"id":"c","label":"Part C","prompt":"In addition to the above cooling measures, outline (4) further actions in your acute resuscitation plan. (4 marks) As you commence cooling measures, the child starts to have a generalised seizure."},{"id":"d","label":"Part D","prompt":"In addition to heatstroke, list (3) possible causes and specific treatment for each. Include drug dose/route where relevant (3 marks) Cause of seizure Treatment"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Higher basal metabolic rate than adults -&gt; produce more heat</div><div class=\"answer-line\">Higher surface area : mass ratio resulting in greater heat absorption in hot environments</div><div class=\"answer-line\">Smaller absolute blood volume resulting in lower blood-born heat dissipation from core</div><div class=\"answer-line\">to surface</div><div class=\"answer-line\">Lower rate of sweating than adults / begin sweating at higher temperatures</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>3.</strong></div><div class=\"answer-line\">Ice packs to neck, groin and axillae (minimise shivering with BZD)</div><div class=\"answer-line\"><strong>4.</strong></div><div class=\"answer-line\">Cool IVF 4°C</div><div class=\"answer-line\"><em>NOT antipyretics, evidence for invasive measures lacking, cold immersion impractical</em></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td><strong>2.</strong></td><td><strong>Septic screen and commence broad spectrum antibiotics</strong></td></tr><tr><td><strong>3.</strong></td><td>Intubate, sedate and paralyse if rectal temp &gt;40 degC despite initial cooling measures</td></tr><tr><td><strong>4.</strong></td><td>Seek and treat complications eg pulmonary oedema, DIC, AKI</td></tr><tr><td colspan=\"2\">Ensure child on continuous cardiac and core rectal temperature monitoring, IDC</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>IV bolus 2mL/kg 10% dextrose</strong></td><td></td></tr><tr><td>Hyponatraemia</td><td>IV bolus 3mL/kg 3% saline (repeat 2x until</td></tr><tr><td>cessation of seizure</td><td></td></tr><tr><td>Febrile convulsion</td><td>IV midazolam 0.15mg/kg</td></tr><tr><td>Supportive, ongoing cooling</td><td></td></tr><tr><td>Cerebral oedema</td><td>IV midazolam 0.15mg/kg</td></tr><tr><td>Nurse 30° head up</td><td></td></tr><tr><td>Pre-existing seizure disorder</td><td>IV midazolam 0.15mg/kg</td></tr><tr><td>IV phenytoin/leviteracitam</td><td></td></tr><tr><td>Cerebral haemorrhage 2° to DIC</td><td>Neuroprotective measures and neuroSx</td></tr><tr><td>referral</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"A 72-year-old gentleman presents to ED with increasing low back pain over the past 6 weeks. This pain is relentless, causing sleepless nights. The patient had previously presented to hospital and was discharged with a diagnosis of a muscle strain. He has not improved with anti-inflammatories and physiotherapy. He also complains of feeling generally fatigued. Vital signs today are :\n\nHR\n\nBP\n126/85\n\nRR\n\nSats\n97% RA\n\nTemp\n36 ̊C Initial blood test results :\n\nNa\n141\n\nK\n4.1\n\nCl\n103\n\nHCO3\n\nUrea\n12.4\n\nCreatinine\n204\nBaseline 85\nCalcium Corr 3.45","parts":[{"id":"a","label":"Part A","prompt":"Given this clinical picture, what historical features will you explore to confirm your diagnosis? (4 marks)"},{"id":"b","label":"Part B","prompt":"List and justify (3) SPECIFIC investigations that can help confirm your diagnosis. (3 marks)"},{"id":"c","label":"Part C","prompt":"State your management priorities for this patient in the emergency department. (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Constitutional symptoms: lethargy, night sweats, fever, weight loss, anorexia</td></tr><tr><td></td><td>Neurological symptoms: related to spinal cord compression, autonomic dysfunction</td></tr><tr><td colspan=\"2\">(urinary retention), association with carpel tunnel syndrome</td></tr><tr><td></td><td>History of pathological fractures</td></tr><tr><td></td><td>Recurrent infections – association with pneumococcus, shingles</td></tr><tr><td></td><td>Related to anaemia – dyspnoea, weakness, dizziness, chest pain</td></tr><tr><td></td><td>Related to hyperviscosity – blurred vision, headaches, dizziness, neuro deficit</td></tr><tr><td colspan=\"2\">Related to hypercalcaemia: confusion, somnolence, constipation</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>FBC – anaemia and thrombocytopaenia due to marrow infiltration</td></tr><tr><td></td><td>CT skeletal survey – lytic lesions esp skull, ribs, spine and long bones</td></tr><tr><td></td><td>Serum electrophoresis – detects and quantifies amount of monoclonal Ig</td></tr><tr><td></td><td>24-hour urine protein electrophoresis - monoclonal antibodies/BJP</td></tr><tr><td></td><td>(UA for proteinuria ½ mark)</td></tr><tr><td colspan=\"2\">Bone marrow aspirate and trephine</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td><strong>Pain management</strong> : ideally opioid with reasonable dose and route, avoidance of</td></tr><tr><td colspan=\"2\">NSAIDs due to renal impairment</td></tr><tr><td></td><td><strong>Management of hypercalcaemia</strong> : aggressive IV rehydration with 0.9% saline to</td></tr><tr><td colspan=\"2\">euvolaemia then aiming UO 1-2mL/kg/hr, IV bisphosphonates +/- calcitonin +/-</td></tr><tr><td colspan=\"2\">corticosteroids</td></tr><tr><td></td><td>Management of renal failure : avoid nephrotoxins, IVF</td></tr><tr><td></td><td>Blood transfusion for symptomatic anaemia</td></tr><tr><td></td><td>Early consultation with haematology, nephrology +/ neurosurgery/orthopaedics if</td></tr><tr><td colspan=\"2\">significant spinal cord/bony injury</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"A 63-year-old man presents to your ED feeling unwell with a painful rash. He has a\nbackground history of metastatic melanoma and was commenced on nivolumab and\nipilimumab 3-4 weeks previously.","parts":[{"id":"a","label":"Part A","prompt":"Give (2) positive findings and the most-likely diagnosis. (3 marks) Your medical student asks you to explain the difference between these checkpoint inhibitor drugs (CPIs) and traditional chemotherapy."},{"id":"b","label":"Part B","prompt":"Complete the table below with brief explanations. (2 marks) Mechanism Adverse effects/ED presentation Checkpoint inhibitors Traditional chemo"},{"id":"c","label":"Part C","prompt":"List (3) adverse effects of CPIs from (3) different organ systems. (3 marks)"},{"id":"d","label":"Part D","prompt":"Briefly outline your management plan. (4 marks)"}],"propPages":["asset:img3ca1a77d8145b8f683","asset:img6b811c00bf3d61e92a"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Widespread purplish maculopapular rash involving the torso</div><div class=\"answer-line\">Desquamation and haemorrhagic crusting of the oral mucosa</div><div class=\"answer-line\"><strong>Diagnosis : </strong> likely Stevens-Johnson Syndrome(SJS)/Toxic Epidermal Necrolysis (TEN) - like</div><div class=\"answer-line\">reaction secondary to checkpoint inhibitor drugs</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Immune-activation via T-cell</td><td>Immune-related adverse events</td><td></td></tr><tr><td colspan=\"3\">stimulation (cytotoxic CD4+ and CD8+</td></tr><tr><td colspan=\"3\">cells)</td></tr><tr><td><strong>Traditional </strong></td><td>Nonspecific cytotoxicity targeting</td><td>Myelosuppression-related issues eg.</td></tr><tr><td>rapidly dividing cells</td><td>infection/febrile neutropenia</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Most commonly</td></tr><tr><td>1.</td><td><em>Dermatological toxicity. (dermatitis, also DRESS, SJS/TEN) – already give so no </em></td></tr><tr><td colspan=\"2\"><em>marks</em></td></tr><tr><td>2.</td><td>Gastrointestinal toxicity (colitis)</td></tr><tr><td>3.</td><td>Endocrinopathies (hypophysitis, adrenalitis, thyroiditis)</td></tr><tr><td colspan=\"2\">Less commonly</td></tr><tr><td>4.</td><td>Hepatotoxicity (hepatitis)</td></tr><tr><td>5.</td><td>Pulmonary toxicity (pneumonitis)</td></tr><tr><td>6.</td><td>Rheumatological toxicity (arthritis/myositis)</td></tr><tr><td>7.</td><td>Neurological toxicity (MG/GBS)</td></tr><tr><td>8.</td><td>Nephrotoxicity</td></tr><tr><td>9</td><td>Ocular toxicity</td></tr><tr><td>10.</td><td>Cardiotoxicity (myopericarditis, heart failure)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Immediate cessation of CPIs and any other potential offending agents</div><div class=\"answer-line\">Specific : skin care (topical emollients, topical steroids), systemic steroids</div><div class=\"answer-line\">(methylpred 1mg/kg/day IV) +/- IVIg depending on severity</div><div class=\"answer-line\">Supportive care : adequate analgesia, fluids and electrolyte replacement,</div><div class=\"answer-line\">thermoregulation, nutritional support</div><div class=\"answer-line\">Admission with multidisciplinary approach to care including medical</div><div class=\"answer-line\">oncology/immunology/dermatology teams if available</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"A 3-year-old girl presents to your rural ED with 2 days of sore throat, diarrhoea, fevers and increasing work of breathing. She has no significant past medical history, no regular medications and vaccinations are up to date. She appears lethargic and her initial observations are as follows:\n\nRR\n\nSats\n91% RA\n\nHR\n190 CRT 5 seconds\n\nTemp\n38.5 ̊C She undergoes a mobile chest X-ray in resus :","parts":[{"id":"a","label":"Part A","prompt":"State the MOST LIKELY diagnosis and 2 causative agents (1/2 mark each). (2 marks)"},{"id":"b","label":"Part B","prompt":"List (3) differential diagnoses for the X-ray appearance. (3 marks)"},{"id":"c","label":"Part C","prompt":"List and justify (6) investigations you would perform in this child. (6 marks)"},{"id":"d","label":"Part D","prompt":"List (2) indications for chest drain insertion in a child with this clinical presentation. (2 marks)"},{"id":"e","label":"Part E","prompt":"Outline (5) INITIAL management priorities for this child. (5 marks)"}],"propPages":["asset:imge3843ef6dd8ab9e7a6"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Most likely parapneumonic effusion secondary to Strep pneumonia, GAS (Strep</div><div class=\"answer-line\">pyogenes or Staph aureus)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Empyema</td></tr><tr><td></td><td>Atypical infection (TB, mycoplasma)</td></tr><tr><td></td><td>Malignant pleural effusion</td></tr><tr><td></td><td>Serositis from rheumatologic cause</td></tr><tr><td></td><td>FB/collapse/consolidation less likely as appearances more in keeping in effusion</td></tr><tr><td colspan=\"2\">(tracheal deviation to contralateral side, rib spreading)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Bedside</div><div class=\"answer-line\">Lung ultrasound - delineate consolidation vs effusion, simple vs loculated effusion for</div><div class=\"answer-line\">drainage</div><div class=\"answer-line\">Cardiac ultrasound - exclude pericardial effusion as source of shock</div><div class=\"answer-line\">VBG - define acid/base status, exclude hypoglycaemia and guide resuscitation</div><div class=\"answer-line\">ECG - exclude SVT as cause of tachycardia</div><div class=\"answer-line\">Laboratory</div><div class=\"answer-line\">FBC - assess for elevated WCC in sepsis</div><div class=\"answer-line\">EUC - identify concurrent renal failure, electrolyte imbalance from diarrhoea</div><div class=\"answer-line\">Blood cultures - guide further antibiotic therapy</div><div class=\"answer-line\">Bacterial Throat swab - identify causative organism to guide therapy, esp iGAS (better</div><div class=\"answer-line\">candidates)</div><div class=\"answer-line\">Viral respiratory panel - identify viral causes for consideration of disease modifying</div><div class=\"answer-line\">drugs eg influenza, COVID</div><div class=\"answer-line\">Pneumococcal PCR (would this be available in a rural centre?)</div><div class=\"answer-line\">CRP (1/2 mark) – to guide disease trajectory</div><div class=\"answer-line\">Radiology - NO MARKS FOR CT (not indicated in this age group or process)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Complicated effusion</td></tr><tr><td></td><td>Severe respiratory distress</td></tr><tr><td></td><td>Septic shock (drain may be required for source control)</td></tr><tr><td colspan=\"2\">Ongoing fever and/or respiratory distress after 48 hours of IV antibiotics</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td><strong>o</strong></td><td>High Flow O2 - 2L/kg titrate to SPO2 &gt;94% and improved WOB OR CPAP</td></tr><tr><td>o</td><td>Intubation and ventilation not appropriate as initial management</td></tr><tr><td></td><td><strong>Treat shock </strong></td></tr><tr><td><strong>o</strong></td><td>NS 10-20ml/kg bolus repeat q5-10 minutes aim for CRT&lt;3s, max 60ml/kg then</td></tr><tr><td colspan=\"2\">start vasopressor therapy</td></tr><tr><td></td><td><strong>Early antibiotic therapy</strong></td></tr><tr><td>o</td><td>Cefotaxime 50mg/kg IV bolus OR<strong> </strong>Ceftriaxone 50mg/kg IV OR<strong> </strong>Ampicillin</td></tr><tr><td colspan=\"2\">50mg/kg IV AND<strong> </strong>Gentamicin 7mg/kg IV OR<strong> </strong>Clindamycin 15mg/kg IV (iGAS</td></tr><tr><td colspan=\"2\">coverage)</td></tr><tr><td></td><td><strong>Supportive </strong></td></tr><tr><td>o</td><td>antipyretics eg paracetamol 15mg/kg PO<strong>,  </strong>ibuprofen 10mg/kg PO  – caution</td></tr><tr><td colspan=\"2\">as may have AKI, seek and treat hypoglycaemia</td></tr><tr><td colspan=\"2\"><strong>Disposition : early organisation of retrieval to tertiary paediatric centre</strong></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"You have just performed an RSI on a patient with acute severe asthma. Shortly after intubation you look up at the monitor and see this capnography trace :","parts":[{"id":"a","label":"Part A","prompt":"What is the MOST CONCERNING cause for this trace? (1 mark)"},{"id":"b","label":"Part B","prompt":"List (3) other situations that could give rise to a flat capnography trace. (3 marks) You manage to troubleshoot the problem. The capnograph trace now looks like this :"},{"id":"c","label":"Part C","prompt":"List (2) relevant findings and give an explanation for each. (2 marks) Relevant finding Explanation"},{"id":"d","label":"Part D","prompt":"Give (6) ventilation parameters for this severe asthmatic and provide a rationale for each. (12 marks) Parameter Rationale"}],"propPages":["asset:imgf4d809f1ac01394cc7","asset:img5787eeef4664515ce4"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Ventilator disconnection</div><div class=\"answer-line\">Airway obstruction eg patient suddenly bit down on the tube</div><div class=\"answer-line\">ETT perforation</div><div class=\"answer-line\">Capnography disconnection</div><div class=\"answer-line\">You manage to troubleshoot the problem.  The capnograph trace now looks like this :</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">More gradual upsloping of transitional</div><div class=\"answer-line\">Airway obstruction</div><div class=\"answer-line\">phase</div><div class=\"answer-line\">Absence of alpha angle</div><div class=\"answer-line\">Bronchoconstriction is so severe the</div><div class=\"answer-line\">deadspace has not finished emptying before</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Lowest possible FiO2 titrated to</td><td>Minimises V/Q mismatch (hyperoxia diverts blood</td></tr><tr><td>sats 90-92%</td><td>to poorly ventilated alveoli)</td></tr><tr><td>Low tidal volume 5-7mL/kg IBW</td><td>Lung protective</td></tr><tr><td>RR 6-10/min</td><td>Prevent dynamic hyperinflation</td></tr><tr><td>I:E ratio 1:3-4</td><td>Prevent dynamic hyperinflation</td></tr><tr><td>Pmax &lt;40cmH20</td><td>High airway pressures therefore need to set higher</td></tr><tr><td>to deliver a breath</td><td></td></tr><tr><td>Plateau pressure &lt;20cmH20</td><td>Prevent barotrauma</td></tr><tr><td>Minimal PEEP (5cmH20)</td><td>Splints small airways open in expiration, helps with</td></tr><tr><td>CO2 clearance</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>https://derangedphysiology.com/main/cicm-primary-exam/required-reading/respiratory-</td><td>system/Chapter%205593/abnormal-capnography-waveforms-and-their-interpretation</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}];
